/* Separate remote pricing from a visit that is required before pricing. */
async function routeQuoting(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!['new','assessment'].includes(jobStage(j)))return;if(await commit(()=>{j.reviewedAt=now();j.opsAction='quoting';j.assigned=true;j.team=j.team==='Unassigned'?'Sevlink Repairs Team':j.team;addEvent(j,'Remote quoting selected','Sevlink will review the photos and job details before preparing a quote.')})){render();jobDetail(jid);toast('Moved to Quoting. No assessment visit required.')}}
function requestPhotosForm(jid){const j=getJob(jid);if(!j||role!=='sevlink'||jobStage(j)!=='quoting')return;openForm('Request photos for a remote quote.',`<p>${esc(property(j.property)?.name)} · ${esc(j.title)}</p><label>Which photos / details do you need?</label><textarea name="message" rows="4" required maxlength="1500" placeholder="e.g. Please upload one wide photo of the affected area and one close-up of the leak / damaged part."></textarea><div class="notice">The tenant and agency can add photos to this job. The request appears in their portal; WhatsApp and email delivery remain previews.</div>`,'Request photos',async d=>{if(await requestJobPhotos(jid,d.get('message'))){render();jobDetail(jid);toast('Photo request recorded. Job stays in Quoting.')}})}
async function requestJobPhotos(jid,message){const j=getJob(jid);if(!j||role!=='sevlink'||jobStage(j)!=='quoting'||!message?.trim())return false;return commit(()=>{j.photoRequest={status:'Requested',text:message.trim(),at:now()};j.comments.push({author:'Sevlink',text:'Photos requested for a remote quote: '+message.trim(),visibility:'shared',at:now()});notify(j,'Photos requested',j.ref+': '+message.trim())})}
function addJobPhotoForm(jid){const j=getJob(jid);if(!j||j.status==='Completed'||!['manager','tenant'].includes(role))return;openForm('Upload repair photos.',`<p>Photos will be added to this repair so Sevlink can quote remotely where possible.</p>${j.photoRequest?'<div class="notice">'+esc(j.photoRequest.text)+'</div>':''}<label>Photo (JPG / PNG / WebP, up to 5 MB)</label><input name="photo" type="file" required accept="image/jpeg,image/png,image/webp"><label>Photo description (optional)</label><textarea name="note" rows="2" maxlength="1000"></textarea>`,'Upload photo',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}if(await saveJobPhoto(jid,photo,d.get('note'))){render();jobDetail(jid,'history');toast('Photo added for Sevlink to review.')}})}
async function saveJobPhoto(jid,photo,note=''){const j=getJob(jid);if(!j||j.status==='Completed'||!['manager','tenant'].includes(role)||!photo||!imageTypes.includes(photo.type))return false;return commit(()=>{const p={...photo,phase:'before',at:now()};j.photos.push(p);j.beforePhotos.push(p);if(j.photoRequest)j.photoRequest.status='Received';j.comments.push({author:person(),text:'Repair photo uploaded.'+(note?' '+note:''),visibility:'shared',at:now()});notify(j,'Photos received',j.ref+': photos are ready for remote quote review.')})}
const detailBeforeQuoting=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeQuoting(jid,section);const j=getJob(jid);if(!j)return;const show=j.photoRequest||jobStage(j)==='quoting';if(show){const photos=j.beforePhotos||[];$('#jobcontent').insertAdjacentHTML('afterbegin',`<div class="notice"><b>Remote quoting${j.photoRequest?.status==='Requested'?' · awaiting photos':j.photoRequest?.status==='Received'?' · photos received':''}</b><p>${esc(j.photoRequest?.text||'Sevlink can prepare this quote using photos and job details where sufficient.')}</p><small>${photos.length} repair photo${photos.length===1?'':'s'} attached</small>${role!=='sevlink'&&j.status!=='Completed'?`<div class="actions"><button class="primary" onclick="addJobPhotoForm('${jid}')">Upload repair photo</button></div>`:''}</div>${photos.length?`<div class="quote-photos">${photos.map(p=>`<img src="${p.data}" alt="Repair photo for remote quotation">`).join('')}</div>`:''}`)}};
